Q: Can I use a Single WCF method to return a class from multiple classes? A: <p>if i understand you in a correct way you want to perform a operation in WCF that will convert any type that implement some IEnumerate (for instance) to Enumerate object. If is's true here is a code </p>

<pre><code>[DataContract]
[KnownType(typeof(Enumerate1))]
[KnownType(typeof(Enumerate2))]
[KnownType(typeof(EnumerateN))]
// up yo 20
public interface IEnumerate 
{
    [DataMember]
    string Description{ get; set; }
    [DataMember]
    int ID {get; set;}
    //  whatever you need 
}
</code></pre>

<hr>

<pre><code>[ServiceContract]
public interface IService
{
    [OperationContract]
    Enumerator GetEnumerator(IEnumerate obj);
}
</code></pre>

<hr>

<pre><code>public Service: IService
{
      Enumerator GetEnumerator(IEnumerate obj)
      {
         // convert
      }
}
</code></pre>

<p>Hope that's helped you</p>

Q: How to optimize the background parallax to be smoother on scrollbar control? A: <p>I think, you can use the <code>lerp</code> function. As long as we have in our minds the same image jumping or its <em>wildness</em> on the scroll...</p>
<p><strong>EDIT</strong></p>
<p>And generally speaking, if I were you, wherever you have moving elements that depend on an event (and you don't want to deal with calculating a custom scrollbar), I would use Lenis or another library that will smooth the <em>movement</em>...</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>document.addEventListener('DOMContentLoaded', function () {

  const section = document.querySelector('#parallax');

  if (!section) return;

  const lenis = typeof Lenis !== 'undefined'
    ? new Lenis({
        duration: 1.2,
        smoothWheel: true,
        smoothTouch: false,
        wheelMultiplier: 1,
        touchMultiplier: 1.5
      })
    : null;

  let currentY = 0;
  let targetY = 0;

  let currentScale = 1;
  let targetScale = 1;

  const maxOffset = 900;
  const maxZoom = 1.4; // this is visually working, so we keep it

  const smoothing = 0.06;

  function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function lerp(start, end, factor) {
    return start + (end - start) * factor;
  }

  function calculateTargets() {
    const rect = section.getBoundingClientRect();
    const windowHeight = window.innerHeight;
    const sectionHeight = rect.height;

    const totalTravel = windowHeight + sectionHeight;
    const traveled = windowHeight - rect.top;

    let progress = traveled / totalTravel;
    progress = clamp(progress, 0, 1);

    const eased = Math.pow(progress, 1.4);

    targetY = eased * maxOffset;
    targetScale = 1 + eased * maxZoom;
  }

  function animate(time) {
    if (lenis) {
      lenis.raf(time);
    }

    calculateTargets();

    currentY = lerp(currentY, targetY, smoothing);
    currentScale = lerp(currentScale, targetScale, smoothing);

    section.style.setProperty('--parallax-offset', currentY.toFixed(2) + 'px');
    section.style.setProperty('--parallax-scale', currentScale.toFixed(4));

    requestAnimationFrame(animate);
  }

  requestAnimationFrame(animate);
});</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>html {
  scroll-behavior: auto;  /*to disable default scroll behavior*/
}

#parallax {
  position: relative;
  overflow: hidden;
  --parallax-offset: 0px;
  --parallax-scale: 1;
}

#parallax::before {
  content: "";
  position: absolute;
  top: -60%;
  left: 0%;
  width: 80%;
  height: 76%;
  background-image: url('https://i.sstatic.net/Cb72ZEgr.jpg');
  background-size: cover;
  background-position: center 45%;
  background-repeat: no-repeat;
  transform: translate3d(0, var(--parallax-offset), 0) scale(var(--parallax-scale));
  transform-origin: 50% 2%;
  will-change: transform;
  z-index: 0;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  contain: paint;
}

#parallax&gt;.e-con-inner {
  position: relative;
  z-index: 2;
}

@media (min-width: 1530px) {
  #parallax::before {
    top: -70%;
    width: 80%;
    height: 86%;
    transform-origin: 50% 2%;

  }
}

@media (min-width: 580px) and (max-height: 800px) {
  #parallax::before {
    background-image: url('https://i.sstatic.net/EDudN3ZP.jpg');
    top: -80%;
    width: 100%;
    height: 100%;
    transform-origin: 50% 10%;
    background-size: contain;
  }
}

@media (min-width: 1900px) {
  #parallax::before {
    background-image: url('https://i.sstatic.net/JpACme02.jpg');
    background-position: center 0%;
    top: -136%;
    width: 100%;
    height: 112%;
    transform-origin: 50% 10%;
    background-size: contain;
  }
}

@media (min-width: 1900px) and (max-height: 1000px) {
  #parallax::before {
    background-image: url('https://i.sstatic.net/EDudN3ZP.jpg');
    background-position: center 0%;
    top: -100%;
    width: 100%;
    height: 102%;
    transform-origin: 50% 10%;
    background-size: contain;
  }
}

@media (max-width: 1024px) {
  #parallax::before {
    top: -80%;
  }
}

@media (min-width: 360px) and (max-width: 767px) {
  #parallax::before {
    top: -50%;
    left: 10%;
  }
}
#parallax::before {
    transform:
        translate3d(0, var(--parallax-offset), 0)
        scale3d(var(--parallax-scale), var(--parallax-scale), 1);

    will-change: transform;
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
    transform-style: preserve-3d;
    contain: paint;
}
html.lenis,
html.lenis body {
    height: auto;
}

.lenis.lenis-smooth {
    scroll-behavior: auto !important;
}

.lenis.lenis-smooth [data-lenis-prevent] {
    overscroll-behavior: contain;
}

.lenis.lenis-stopped {
    overflow: hidden;
}</code></pre>
